components.css:
.ds-msd, .ds-date-field { position: relative; min-width: 0; }
.ds-msd-trigger, .ds-date-field-trigger { width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0.42rem 0.65rem; border: 1px solid var(--border-strong); border-radius: var(--radius-control); background: var(--surface); color: var(--text-main); font: inherit; font-size: .86rem; text-align: left; cursor: pointer; }
.ds-msd-trigger:hover:not(:disabled), .ds-date-field-trigger:hover { border-color: var(--ghn-blue); }
.ds-msd-trigger.ds-is-open, .ds-date-field-trigger.ds-is-open { border-color: var(--ghn-blue); box-shadow: var(--focus-ring); }
.ds-msd-trigger:disabled { opacity: .6; cursor: not-allowed; background: var(--surface-subtle); }
.ds-msd-trigger.ds-is-filtered { border-color: color-mix(in srgb, var(--ghn-blue) 55%, var(--border-strong)); background: color-mix(in srgb, var(--info-box-bg) 55%, var(--surface)); }
.ds-msd-trigger.ds-is-open .ds-msd-chevron { transform: rotate(180deg); }
.ds-date-field-trigger svg { flex: none; color: var(--text-muted); }
.ds-date-field-trigger .ds-is-placeholder { color: var(--text-muted); }
.ds-msd-trigger:focus-visible, .ds-date-field-trigger:focus-visible { outline: 2px solid var(--action-primary); outline-offset: 2px; box-shadow: var(--focus-ring); }

